/** TypeScript declaration for webpack-bundled audio files. */
declare module '*.ogg' {
  const src: string;
  export default src;
}

/** TypeScript declaration for webpack-bundled image files. */
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.jpg' {
  const src: string;
  export default src;
}
declare module '*.jpeg' {
  const src: string;
  export default src;
}
declare module '*.gif' {
  const src: string;
  export default src;
}
declare module '*.svg' {
  const src: string;
  export default src;
}
